import { NextRequest } from 'next/server'
import { backendProductRoute, resolveParenting } from '@/lib/interpret/backend'

// ─── Parenting Astro ──────────────────────────────────────────────────────────
//
// Generated by the backend (/interpret/parenting/natal): CLAUDE_SYSTEM.md +
// CLAUDE_NATAL_PARENTING.md + CLAUDE_CORE_ASTRO_PARENTING.md, both charts,
// parenting intake, delivery checks. The browser supplies only the child chart_id.

// Same order and names as the backend's VALID_SECTIONS['parenting_natal'].
const PARENTING_SECTIONS = [
  'parenting_lagna', 'parenting_sun', 'parenting_moon', 'parenting_mercury',
  'parenting_venus', 'parenting_mars', 'parenting_jupiter', 'parenting_saturn',
  'parenting_uranus', 'parenting_neptune', 'parenting_pluto',
  'parenting_rahu', 'parenting_ketu',
  'parenting_dignities', 'parenting_purusharthas', 'parenting_dasha',
] as const

export async function POST(request: NextRequest) {
  return backendProductRoute(request, {
    tag:          'interpret-parenting',
    entitlements: ['parenting_astro_report'],
    sections:     PARENTING_SECTIONS,
    path:         '/interpret/parenting/natal',
    resolve:      resolveParenting,
  })
}
